  Widget _anatomyPage() {
    final regions = ['الكل', ...{for (final part in anatomyParts) part.region}];
    final items = anatomyParts.where((part) {
      final matchesRegion = anatomyRegion == 'الكل' || part.region == anatomyRegion;
      final query = anatomyQuery.toLowerCase();
      final matchesQuery = query.isEmpty ||
          part.name.toLowerCase().contains(query) ||
          part.system.toLowerCase().contains(query) ||
          part.function.toLowerCase().contains(query);
      return matchesRegion && matchesQuery;
    }).toList();

    return ListView(
      padding: const EdgeInsets.all(16),
      children: [
        Text('فهرس التشريح (${anatomyParts.length})', style: const TextStyle(fontSize: 24, fontWeight: FontWeight.bold)),
