        TextField(
          onChanged: (value) => setState(() => anatomyQuery = value),
          decoration: InputDecoration(
            hintText: 'ابحث عن بنية تشريحية',
            prefixIcon: const Icon(Icons.search),
            filled: true,
            fillColor: Colors.white,
            border: OutlineInputBorder(borderRadius: BorderRadius.circular(16), borderSide: BorderSide.none),
          ),
        ),
        const SizedBox(height: 10),
        DropdownButtonFormField<String>(
          value: anatomyRegion,
          decoration: const InputDecoration(labelText: 'منطقة الجسم', border: OutlineInputBorder()),
          items: regions.map((region) => DropdownMenuItem(value: region, child: Text(region))).toList(),
          onChanged: (value) => setState(() => anatomyRegion = value ?? 'الكل'),
        ),
        const SizedBox(height: 10),
        Text('النتائج: ${items.length}', style: const TextStyle(color: Colors.black54)),
        ...items.map((part) => Card(
          child: ListTile(
            leading: const Icon(Icons.account_tree_outlined, color: Color(0xFF168C83)),
            title: Text(part.name, style: const TextStyle(fontWeight: FontWeight.bold)),
            subtitle: Text('${part.region} • ${part.system}'),
            trailing: const Icon(Icons.chevron_left),
            onTap: () => Navigator.push(context, MaterialPageRoute(builder: (_) => AnatomyDetailPage(part: part))),
          ),
        )),
        if (items.isEmpty) const Padding(padding: EdgeInsets.all(20), child: Text('لا توجد نتائج مطابقة.')),
      ],
    );
  }

  Widget _bodyPartsPage() {
    final items = bodyParts.where((part) => bodyPartQuery.isEmpty ||
        part.name.contains(bodyPartQuery) ||
        part.system.contains(bodyPartQuery) ||
        part.location.contains(bodyPartQuery)).toList();
    return ListView(
      padding: const EdgeInsets.all(16),
      children: [
        Text('أعضاء الجسم (${bodyParts.length})', style: const TextStyle(fontSize: 24, fontWeight: FontWeight.bold)),
        const SizedBox(height: 8),
        const Text('اللهم صلي و سلم على سيدنا محمد و الشفاء العاجل للجميع.'),
        const SizedBox(height: 12),
        TextField(
          onChanged: (value) => setState(() => bodyPartQuery = value),
          decoration: InputDecoration(
            hintText: 'ابحث عن عضو أو جهاز أو منطقة',
            prefixIcon: const Icon(Icons.search),
            filled: true,
            fillColor: Colors.white,
            border: OutlineInputBorder(borderRadius: BorderRadius.circular(16), borderSide: BorderSide.none),
          ),
        ),
        const SizedBox(height: 10),
        Text('النتائج: ${items.length}', style: const TextStyle(color: Colors.black54)),
        ...items.map((part) => Card(
          child: ListTile(
            leading: const Icon(Icons.health_and_safety_outlined, color: Color(0xFF168C83)),
            title: Text(part.name, style: const TextStyle(fontWeight: FontWeight.bold)),
            subtitle: Text('${part.location} • ${part.system}\n${part.function}', maxLines: 3, overflow: TextOverflow.ellipsis),
            isThreeLine: true,
            trailing: const Icon(Icons.chevron_left),
            onTap: () => Navigator.push(context, MaterialPageRoute(builder: (_) => BodyPartDetailPage(part: part))),
          ),
        )),
        if (items.isEmpty) const Padding(padding: EdgeInsets.all(20), child: Text('لا توجد نتائج مطابقة.')),
      ],
    );
  }

  Widget _diseasePage() {
    final items = diseases.where((disease) {
      final matchesFilter = diseaseFilter == 'الكل' ||
          (diseaseFilter == 'نادر'
              ? disease.rarity.contains('نادر')
              : disease.rarity.contains('شائع'));
      final matchesQuery = diseaseQuery.isEmpty ||
          disease.name.contains(diseaseQuery) ||
          disease.category.contains(diseaseQuery) ||
          disease.summary.contains(diseaseQuery);
      return matchesFilter && matchesQuery;
    }).toList();

    return ListView(
      padding: const EdgeInsets.all(16),
      children: [
        Text('الأمراض (${diseases.length})', style: const TextStyle(fontSize: 24, fontWeight: FontWeight.bold)),
        const SizedBox(height: 10),
        TextField(
          onChanged: (value) => setState(() => diseaseQuery = value),
          decoration: InputDecoration(
            hintText: 'ابحث عن مرض أو جهاز بالجسم',
            prefixIcon: const Icon(Icons.search),
            filled: true,
            fillColor: Colors.white,
            border: OutlineInputBorder(borderRadius: BorderRadius.circular(16), borderSide: BorderSide.none),
          ),
        ),
        const SizedBox(height: 10),
        Wrap(
          spacing: 8,
          children: ['الكل', 'شائع', 'نادر'].map((filter) => ChoiceChip(
            label: Text(filter == 'الكل' ? 'جميع الحالات' : filter == 'شائع' ? 'الشائعة' : 'النادرة'),
            selected: diseaseFilter == filter,
            onSelected: (_) => setState(() => diseaseFilter = filter),
          )).toList(),
        ),
        const SizedBox(height: 10),
        ...items.map((disease) => Card(
          child: ListTile(
            leading: CircleAvatar(
              backgroundColor: disease.rarity.contains('نادر') ? const Color(0xFFFFE9D6) : const Color(0xFFE1F3EF),
              child: const Icon(Icons.medical_information_outlined, color: Color(0xFF168C83)),
            ),
            title: Text(disease.name, style: const TextStyle(fontWeight: FontWeight.bold)),
            subtitle: Text('${disease.category} • ${disease.rarity}\n${disease.summary}', maxLines: 3, overflow: TextOverflow.ellipsis),
            isThreeLine: true,
            trailing: const Icon(Icons.chevron_left),
            onTap: () => Navigator.push(context, MaterialPageRoute(builder: (_) => DiseaseDetailPage(disease: disease))),
          ),
        )),
        if (items.isEmpty) const Padding(padding: EdgeInsets.all(20), child: Text('لا توجد نتائج مطابقة.')),
      ],
    );
  }

  Widget _safetyPage() => ListView(padding: const EdgeInsets.all(16), children: [const Text('السلامة الطبية', style: TextStyle(fontSize: 24, fontWeight: FontWeight.bold)), _safety('اطلب الطوارئ فورًا', 'صعوبة التنفس الشديدة، ألم الصدر الجديد أو الشديد، فقدان الوعي، علامات السكتة الدماغية مثل ضعف مفاجئ أو اضطراب الكلام، النزف الشديد أو التحسس الشديد.'), _safety('لا تغيّر الأدوية بنفسك', 'لا تبدأ مضادًا حيويًا ولا توقف دواءً موصوفًا ولا تغيّر جرعته بناءً على هذه الموسوعة. استشر طبيبًا أو صيدليًا.'), _safety('الأطفال والحمل والأمراض المزمنة', 'قد تختلف الإرشادات بحسب العمر والحمل ووظائف الكلى والكبد والأدوية الأخرى. اطلب نصيحة مختصة.'), _safety('حدود المعلومات', 'الأعراض نفسها قد تنتج عن أسباب متعددة. التطبيق لا يجري فحصًا سريريًا أو تحاليل أو تصويرًا.'), _safety('المراجع', 'المصادر مكتوبة داخل صفحات الحالات. الروابط لا تفتح تلقائيًا ولا يجري التطبيق مزامنة للمعلومات.')]);
  Widget _safety(String title, String body) => Card(margin: const EdgeInsets.only(top: 10), child: Padding(padding: const EdgeInsets.all(16), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text(title, style: const TextStyle(fontWeight: FontWeight.bold)), const SizedBox(height: 6), Text(body, style: const TextStyle(height: 1.5))])));
}

